import{_ as n,o as t,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Financer un événement","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/activites/financement-evenements.md","filePath":"src/guide/activites/financement-evenements.md"}'),s={name:"guide/activites/financement-evenements.md"};function o(i,e,u,l,p,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="financer-un-evenement" tabindex="-1">Financer un événement <a class="header-anchor" href="#financer-un-evenement" aria-label="Permalink to &quot;Financer un événement&quot;">​</a></h1><p>Un financeur peut soutenir un événement communautaire de NextBoxx par un <strong>apport</strong>, en argent ou en nature. Le <strong>Chargé d&#39;événements</strong> constate la réception des apports et tient les dépenses.</p><h2 id="devenir-financeur-d-evenement" tabindex="-1">Devenir Financeur d&#39;événement <a class="header-anchor" href="#devenir-financeur-d-evenement" aria-label="Permalink to &quot;Devenir Financeur d&#39;événement&quot;">​</a></h2><p>Le rôle <strong>Financeur d&#39;événement</strong> reste ouvert aux <strong>comptes individu</strong> comme aux comptes organisation. Demandez-le dans <strong>Paramètres → Rôles</strong> : le Chargé d&#39;événements l&#39;examine. Il vous est aussi attribué automatiquement quand le Chargé saisit un apport en votre nom.</p><h2 id="declarer-un-apport" tabindex="-1">Déclarer un apport <a class="header-anchor" href="#declarer-un-apport" aria-label="Permalink to &quot;Déclarer un apport&quot;">​</a></h2><p>Dans <strong>Activités → Mes financements</strong>, <strong>Déclarer un apport</strong> demande :</p><ul><li>l&#39;<strong>événement</strong> : il doit être publié, non annulé et pas encore terminé ;</li><li>la <strong>nature</strong> : financier, en nature ou autre ;</li><li>une <strong>description</strong> ;</li><li>le <strong>montant</strong> en FCFA, ou, pour un apport en nature ou autre, sa <strong>valorisation</strong> en FCFA.</li></ul><p>Votre apport reste <strong>Déclaré</strong> jusqu&#39;à ce que NextBoxx <strong>constate sa réception</strong>, ou le <strong>refuse</strong> avec un motif que vous recevez par e-mail. Il n&#39;est jamais compté automatiquement, et aucune facture n&#39;est émise.</p><p>Quand l&#39;apport est reçu, NextBoxx vous envoie votre <strong>convention de financement</strong> (<code>CONVE-NB-AAAA-XXX</code>) par e-mail. Elle ne se signe pas électroniquement.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p><strong>Mes financements</strong> liste vos apports, avec leur statut (<strong>Déclaré</strong>, <strong>Reçu</strong>, <strong>Refusé</strong>, <strong>Annulé</strong>) et leur convention. Pour chaque événement que vous financez, vous voyez le <strong>total des apports reçus</strong>, le <strong>total des dépenses</strong> et le <strong>solde net</strong>. Vous ne voyez ni le détail des autres financeurs, ni celui des dépenses.</p><p>Si l&#39;événement est <strong>annulé</strong>, vos apports déclarés sont annulés. Les apports déjà reçus restent au bilan et vous êtes prévenu ; leur restitution se règle hors de Kura.</p><h2 id="le-suivi-par-le-charge-d-evenements" tabindex="-1">Le suivi par le Chargé d&#39;événements <a class="header-anchor" href="#le-suivi-par-le-charge-d-evenements" aria-label="Permalink to &quot;Le suivi par le Chargé d&#39;événements&quot;">​</a></h2><p>Sur la fiche d&#39;un événement, la rubrique <strong>Financement</strong> montre les apports reçus, les dépenses et le solde net, avec la liste des apports.</p><ul><li><strong>Constater la réception</strong> d&#39;un apport déclaré, avec la date : il entre au bilan et sa convention de financement est émise et envoyée.</li><li><strong>Refuser</strong> un apport, avec un motif communiqué au financeur.</li><li><strong>Saisir un apport</strong> pour un compte existant, par exemple après coup, même après la fin de l&#39;événement. Indiquez l&#39;adresse e-mail du compte ; si vous renseignez « Déjà reçu le », la réception est constatée aussitôt. Le compte reçoit le rôle Financeur d&#39;événement.</li><li><strong>Ajouter une dépense</strong> : libellé, montant, date et justificatif facultatif (PDF, JPG ou PNG, 5 Mo au plus). Vous pouvez la corriger ou la supprimer ; chaque saisie, correction ou suppression est tracée au journal.</li><li><strong>Noter la restitution</strong> d&#39;un apport reçu après l&#39;annulation de l&#39;événement, avec sa date : le remboursement se règle hors de Kura et l&#39;apport reste au bilan.</li></ul><p>Le <strong>solde net</strong> est le total des apports reçus moins les dépenses.</p>',16)])])}const g=n(s,[["render",o]]);export{m as __pageData,g as default};
